 static Object runTable(Object buffer,Object orientation)throws Exception{Object factory=Class.forName("org.audiveris.omr.run.RunTableFactory").getConstructor(Class.forName("org.audiveris.omr.run.Orientation")).newInstance(orientation);for(Method m:factory.getClass().getMethods())if(m.getName().equals("createTable")&&m.getParameterCount()==1&&m.getParameterTypes()[0].isInstance(buffer))return m.invoke(factory,buffer);throw new NoSuchMethodException("createTable buffer");}
